import java.sql.*;
public class BatchInsertBenchmark{
 static final String URL=System.getenv().getOrDefault("DB_URL","jdbc:mysql://localhost:3306/assignment5"),USER=System.getenv().getOrDefault("DB_USER","root"),PASS=System.getenv().getOrDefault("DB_PASSWORD","");
 static Connection open()throws SQLException{return DriverManager.getConnection(URL,USER,PASS);}
 static void schema(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS bus_passes(pass_id VARCHAR(20) PRIMARY KEY,register_no VARCHAR(20),student_name VARCHAR(80),route_no INT,amount DECIMAL(10,2) NOT NULL CHECK(amount>=0))");}}
 static void clear(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate("DELETE FROM bus_passes");}}
 static void bind(PreparedStatement p,int i)throws SQLException{p.setString(1,"P"+i);p.setString(2,"R"+i);p.setString(3,"Student"+i);p.setInt(4,5);p.setBigDecimal(5,new java.math.BigDecimal("3500.00"));}
 static long statement(Connection c,int n)throws SQLException{clear(c);long t=System.nanoTime();try(Statement s=c.createStatement()){for(int i=0;i<n;i++)s.executeUpdate("INSERT INTO bus_passes VALUES('S"+i+"','R"+i+"','Student"+i+"',5,3500.00)");}return(System.nanoTime()-t)/1_000_000;}
 static long prepared(Connection c,int n)throws SQLException{clear(c);long t=System.nanoTime();try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_passes VALUES(?,?,?,?,?)")){for(int i=0;i<n;i++){bind(p,i);p.executeUpdate();}}return(System.nanoTime()-t)/1_000_000;}
 static long batch(Connection c,int n)throws SQLException{clear(c);long t=System.nanoTime();boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_passes VALUES(?,?,?,?,?)")){for(int i=0;i<n;i++){bind(p,i);p.addBatch();if((i+1)%1000==0)p.executeBatch();}p.executeBatch();c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}return(System.nanoTime()-t)/1_000_000;}
 static void rollbackTest(Connection c)throws SQLException{clear(c);boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO bus_passes VALUES(?,?,?,?,?)")){for(int i=0;i<10;i++){p.setString(1,"T"+i);p.setString(2,"R"+i);p.setString(3,"Test"+i);p.setInt(4,5);p.setBigDecimal(5,new java.math.BigDecimal(i==5?"-1.00":"100.00"));p.addBatch();}p.executeBatch();c.commit();}catch(SQLException e){c.rollback();System.out.println("Invalid amount rolled back: "+e.getMessage());}finally{c.setAutoCommit(old);}try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM bus_passes")){r.next();System.out.println("Rows after rollback: "+r.getInt(1));}}
 public static void main(String[]args)throws Exception{try(Connection c=open()){schema(c);for(int n:new int[]{10,1000,10000,100000})System.out.printf("%d rows Statement=%dms Prepared=%dms Batch=%dms%n",n,statement(c,n),prepared(c,n),batch(c,n));rollbackTest(c);}}
}